head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.listcount = 0;
scwin.prevRow = -1;

// 회사명변경내역

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");
        const fn_GetPar = parentWin.fn_GetParam;
        if (fn_GetPar !== undefined) {
            fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
        }
        await scwin.ins_search(scwin.param1);
        txb_SEQ.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.listcount = rowcount;
        // CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리
        txb_ISUR_CD.setValue(scwin.param1);
        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn("no_data");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
        // CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리
        fn_CtrlBtn("no_data");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.ins_process("02");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.btn_save_onclick" });
    }
};

/**
