/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        await scwin.ins_remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.btn_delete_onclick" });
