/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 저장"));
        await scwin.ins_search(scwin.param1);
        $c.frame.path("../").ins_detail(scwin.param1);
        // frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_save_OnFail = function() {
    try {
        alert_tr_error(trs_save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name trs_modify_OnSuccess
 * @description modify On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_modify_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 수정"));
        // frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.trs_modify_OnSuccess" });
    }
};

