};

/**
 * @method
 * @name trs_remove_OnSuccess
 * @description remove On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_remove_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 삭제"));
        await scwin.ins_search(scwin.param1);
        $c.frame.path("../").ins_detail(scwin.param1);
        // frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90900.trs_remove_OnSuccess" });
    }
};

/**
 * @method
