 */
scwin.trs_remove_OnFail = function() {
    try {
        alert_tr_error(trs_remove);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.trs_remove_OnFail" });
    }
};

/**
 * @method
 * @name img_CHG_DD_onclick
 * @description img_CHG_DD 클릭 이벤트
 * @returns {void}
