 */
scwin.img_CHG_DD_onclick = function() {
    try {
        popUpCalendar2(edt_CHG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.img_CHG_DD_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {

};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_new_onclick = function() {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.btn_new_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        dts_List.undoRow(scwin.prevRow);
        scwin.prevRow = row;
        fn_CtrlBtn("update");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90900.dts_List_OnRowPosChanged" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 회사명변경내역  조회 한다.
 * @param {*} isurcd isurcd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function(isurcd) {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ShowWin(grd_Grid); // 그리드명을 표기

};

/**
 * @method
 * @name ins_process
 * @description 회사명변경내역  저장,수정  한다. screenProcsTpCd 02 저장 screenProcsTpCd 03 수정
 * @param {String} screenProcsTpCd screenProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_process = async function(screenProcsTpCd) {
    // alert("dts_Out.Text " +dts_Out.Text);
    // alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));

    if (edt_CHG_DD.getValue() === "" || edt_CHG_DD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "변경일"));
        edt_CHG_DD.focus();
        return;
    }
    if (edt_CHG_DD.getValue().length === 8) {

    } else {
        await $c.win.alert("올바른 날짜를 입력하세요.");
        edt_CHG_DD.focus();
        return;
    }
    if (txb_ISUR_NM.getValue() === "" || txb_ISUR_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "변경전발행기관명"));
        txb_ISUR_NM.focus();
        return;
    }
    if (txb_MEMO_CONTN.getValue() === "" || txb_MEMO_CONTN.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "메모"));
        txb_MEMO_CONTN.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_MEMO_CONTN, 100, "메모")) {
        // txb_MEMO_CONTN.value = "";
        txb_MEMO_CONTN.focus();
        return false;
    }
    if (scwin.listcount === 0) {

    } else {
        if (!$c.cp.isModified(dts_List)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (screenProcsTpCd === "02") {
            // 등록시 중복체크
            if (scwin.dup() === false) {
                await $c.win.alert("변경일 중복입니다.");
                return;
            }
        }
    }
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/CmmInfoAction.do",
        ref : "dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_remove
 * @description 회사명변경내역  삭제  한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {
    if (dts_List.getRowCount() === 1) {
        await $c.win.alert("정보가 1건입니다. 삭제불가입니다. 수정만 가능합니다.");
        return;
    }
    const rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_ListDelete.insertRow();
        dts_ListDelete.setCellData(1, "SEQ", dts_List.getCellData(dts_List.getRowPosition(), "SEQ"));

        // alert("dts_ListDelete.ISUR_CD "+ dts_ListDelete.NameValue(dts_ListDelete.RowPosition,"ISUR_CD"));

        trs_remove.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_remove",
            action : "/CmmInfoAction.do",
            ref : "dts_ListDelete",
            target : "trs_remove=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name new
 * @description 조회버튼 클릭시 신규등록을 위한 dataset 세팅
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowPosition(), "ISUR_CD", scwin.param1);
    fn_CtrlBtn("insert");
};

/**
 * @method
 * @name dup
 * @description 변경일 중복검사
 * @returns {void}
 * @hidden N
 */
scwin.dup = function() {
    let dupcnt = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        // alert(dts_List.NameString(i, "CHG_DD") +" " + getObjectValue(edt_CHG_DD));
        if (dts_List.getCellData(i, "CHG_DD") === edt_CHG_DD.getValue()) {
            dupcnt++;
        }
    }
    // alert("dupcnt " +dupcnt);
    if (Number(dupcnt) < 2) {
        return true;
    } // 중복아님
    else {
        return false;
    } // 중복

};
